INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA4_CC_2014_01:CODIGO_CIVIL:1451','mayalex_normativos','02_CIVIL','Beneficio de competencia es el que se concede a ciertos deudores para no ser obligados a pagar más de lo que buenamente puedan, dejándoseles, en consecuencia, lo indispensable para una modesta subsistencia, según su clase y circunstancias, y con cargo de devolución cuando mejoren de fortuna.','1451','Código Civil de Honduras (Decreto del Poder Ejecutivo del 8 de febrero de 1906)','{"norm_id":"HN:CODIGO_CIVIL","instrumento_id":"CODIGO_CIVIL","ingest_batch":"OLA4_CC_2014_01","ola":"OLA4","ordinal":1451,"instrumento":"Decreto del Poder Ejecutivo, 8 de febrero de 1906","decreto_habilitante_anc":"76 (Asamblea Nacional Constituyente)","texto_origen":"PDF_CONSOLIDADO_PJ_2014_SANEADO","edicion_fuente":"Edición consolidada del Poder Judicial de Honduras (www.poderjudicial.gob.hn), \"CodigoCivil(Actualizado2014).pdf\" -- elegida por el CLO sobre la variante \"Código Civil (mayo 2018).pdf\" tras comparación manual línea a línea de las últimas 25 páginas de ambas: cuerpo idéntico Art.1-2372, la única diferencia es que esta edición trae el apéndice \"DEROGACIONES Y REFORMAS SEGÚN FECHAS DE DEROGACION Y REFORMAS\" (pp.422-423), ausente en la variante de mayo 2018. Notas al pie individuales (43, numeración secuencial 1..43) usadas como fuente primaria de cada cita de decreto -- más precisas que el apéndice, que contiene un error verificado (Art.511 listado como derogado en el apéndice, pero reformado según su propia nota al pie 19) y una repetición de imprenta (rango \"276 al 330\" y el número \"262\" aparecen dos veces en el ítem 12 del propio apéndice).","pdf_sha256":"c1ebf3ce42af93e567f733555a7a1fafbd41748a00852c5edf0f6537c1e1cb34","fragmento_fuente_sha256":"2a68211884e905f4e9b20560517c4b3891488d3b6e556aca3957274320c6d7ae","article_sha256":"8b67299bc1428ca0dd1d8527245ed942972b95e70024076868e1667a869f75a7","constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cc_1906_a1451","cotejo_compilacion_csj":1,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada del Poder Judicial (2014) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_CIVIL','1451','8b67299bc1428ca0dd1d8527245ed942972b95e70024076868e1667a869f75a7','OLA4_CC_2014_01',now()),
('OLA4_CC_2014_01:CODIGO_CIVIL:1452','mayalex_normativos','02_CIVIL','El acreedor es obligado a conceder este beneficio:

1. A sus descendientes o ascendientes y suegros; no habiendo estos irrogado al acreedor ofensa alguna de las clasificadas entre las causas de indignidad para heredar.

2. A su cónyuge, no estando de él separado de cuerpos por su culpa.

3. A sus hermanos, con tal que no se hayan hecho culpables para con el acreedor de una ofensa igualmente grave que las indicadas en el número primero de este artículo.

4. A sus consocios en el mismo caso; pero solo en las acciones recíprocas que nazcan del contrato de sociedad.

5. Al donante; pero solo en cuanto se trata de hacerlo cumplir la donación prometida.

6. Al deudor de buena fe, que hizo cesión de bienes y es perseguido en los que después ha adquirido para el pago completo de las deudas anteriores a la cesión; pero solo le deben este beneficio los acreedores a cuyo favor se hizo.','1452','Código Civil de Honduras (Decreto del Poder Ejecutivo del 8 de febrero de 1906)','{"norm_id":"HN:CODIGO_CIVIL","instrumento_id":"CODIGO_CIVIL","ingest_batch":"OLA4_CC_2014_01","ola":"OLA4","ordinal":1452,"instrumento":"Decreto del Poder Ejecutivo, 8 de febrero de 1906","decreto_habilitante_anc":"76 (Asamblea Nacional Constituyente)","texto_origen":"PDF_CONSOLIDADO_PJ_2014_SANEADO","edicion_fuente":"Edición consolidada del Poder Judicial de Honduras (www.poderjudicial.gob.hn), \"CodigoCivil(Actualizado2014).pdf\" -- elegida por el CLO sobre la variante \"Código Civil (mayo 2018).pdf\" tras comparación manual línea a línea de las últimas 25 páginas de ambas: cuerpo idéntico Art.1-2372, la única diferencia es que esta edición trae el apéndice \"DEROGACIONES Y REFORMAS SEGÚN FECHAS DE DEROGACION Y REFORMAS\" (pp.422-423), ausente en la variante de mayo 2018. Notas al pie individuales (43, numeración secuencial 1..43) usadas como fuente primaria de cada cita de decreto -- más precisas que el apéndice, que contiene un error verificado (Art.511 listado como derogado en el apéndice, pero reformado según su propia nota al pie 19) y una repetición de imprenta (rango \"276 al 330\" y el número \"262\" aparecen dos veces en el ítem 12 del propio apéndice).","pdf_sha256":"c1ebf3ce42af93e567f733555a7a1fafbd41748a00852c5edf0f6537c1e1cb34","fragmento_fuente_sha256":"f12b60ebe4a376da084401be83ba424c1b6098faaf544a538d049d795ce0b669","article_sha256":"6deacadca971d06225035e9f66e4cf9c39bba1dd1493932ab7f3c63e8f45db65","constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cc_1906_a1452","cotejo_compilacion_csj":1,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motiv