DO $do$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA4_CC_2014_01' AND metadata->>'norm_id' = 'HN:CODIGO_CIVIL'
    AND instrumento_id = 'CODIGO_CIVIL' AND jurisdiccion = 'HN' AND encode(sha256(convert_to(contenido, 'UTF8')), 'hex') = hash_contenido AND revision_pendiente = true AND es_norma_vigente IS NULL;
  IF n <> 2372 THEN RAISE EXCEPTION 'post-insert prod (ocultas, hash correcto): % filas (esperadas 2372)', n; END IF;
